import * as React from 'react'
import { cn } from '@/lib/rillmark-utils'
export const Card = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(function Card({ className, ...props }, ref) {
  return <div ref={ref} className={cn('rounded-2xl rounded-tr-md border border-border bg-card text-card-foreground', className)} {...props}/>
})
export function CardHeader({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) { return <div className={cn('flex flex-col gap-1.5 p-5', className)} {...props}/> }
export interface CardTitleProps extends React.HTMLAttributes<HTMLHeadingElement> { as?: 'h2' | 'h3' | 'h4' | 'h5' | 'h6' }
export function CardTitle({ as: Heading = 'h3', className, ...props }: CardTitleProps) { return <Heading className={cn('text-lg font-semibold tracking-tight', className)} {...props}/> }
export function CardDescription({ className, ...props }: React.HTMLAttributes<HTMLParagraphElement>) { return <p className={cn('text-sm leading-relaxed text-muted-foreground', className)} {...props}/> }
export function CardContent({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) { return <div className={cn('p-5 pt-0', className)} {...props}/> }
export function CardFooter({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) { return <div className={cn('flex flex-wrap items-center gap-3 border-t border-border p-5', className)} {...props}/> }
